// The repo list. If REPO_LIST_URL is set it must return a JSON array of
// { name, url, target? } entries; otherwise the static list below is used.
const repos = [];

if ($env.REPO_LIST_URL) {
  const list = await this.helpers.httpRequest({
    url: $env.REPO_LIST_URL,
    method: 'GET',
    json: true,
  });
  for (const r of Array.isArray(list) ? list : (list.repos || [])) {
    repos.push({ name: r.name, url: r.url || '', target: r.target || '' });
  }
} else {
  repos.push(
    { name: 'go-gin', url: 'https://github.com/gin-gonic/gin' },
    { name: 'java-springboot', url: 'https://github.com/spring-projects/spring-boot' },
    { name: 'os-nova', url: 'https://github.com/openstack/nova' },
  );
}

return repos.filter((r) => r.name && (r.url || r.target)).map((r) => ({ json: r }));

const stdout = $json.stdout || '';

const extract = (label) => {
  const m = stdout.match(new RegExp('=== ' + label + ' ===\\n([\\s\\S]*?)(?===)'));
  return m ? m[1].split('\n').map((s) => s.trim()).filter(Boolean) : [];
};

const summaryFiles = extract('SUMMARY');
const artifactDirs = parseInt((stdout.match(/=== ARTIFACT DIRS ===\n(\d+)/) || [])[1] || '0', 10);
const qualityDirs = parseInt((stdout.match(/=== QUALITY DIRS ===\n(\d+)/) || [])[1] || '0', 10);

return [{
  json: {
    summaryFiles,
    artifactDirs,
    qualityDirs,
    finishedAt: new Date().toISOString(),
  },
}];
